UPDATE translations SET value = 'Le menu des analyses par pays couvre les étapes exactes d''immatriculation, les spécifications techniques et les sanctions pour chacune des 66 juridictions suivies ici.' WHERE namespace = 'edu-certified-providers' AND lang = 'fr' AND key = 'sec5.card3.body' AND value = 'Le menu des analyses par pays couvre les étapes exactes d''immatriculation, les spécifications techniques et les sanctions pour chacune des 60 juridictions suivies ici.';
UPDATE translations SET value = 'This is a <strong>starting set of verified links</strong>, not a complete map of all 66 tracked jurisdictions. Every link below was checked directly against the named government/authority''s own website. Several countries in this tracker don''t run a public accreditation registry at all — see the note in Section 3 before assuming one exists.' WHERE namespace = 'edu-certified-providers' AND lang = 'en' AND key = 'statusBanner.text' AND value = 'This is a <strong>starting set of verified links</strong>, not a complete map of all 60 tracked jurisdictions. Every link below was checked directly against the named government/authority''s own website. Several countries in this tracker don''t run a public accreditation registry at all — see the note in Section 3 before assuming one exists.';
UPDATE translations SET value = 'Este es un <strong>conjunto inicial de enlaces verificados</strong>, no un mapa completo de las 66 jurisdicciones seguidas. Cada enlace de abajo se comprobó directamente en el propio sitio web del gobierno/autoridad mencionado. Varios países de este seguimiento simplemente no gestionan un registro público de acreditación — vea la nota de la Sección 3 antes de asumir que existe uno.' WHERE namespace = 'edu-certified-providers' AND lang = 'es' AND key = 'statusBanner.text' AND value = 'Este es un <strong>conjunto inicial de enlaces verificados</strong>, no un mapa completo de las 60 jurisdicciones seguidas. Cada enlace de abajo se comprobó directamente en el propio sitio web del gobierno/autoridad mencionado. Varios países de este seguimiento simplemente no gestionan un registro público de acreditación — vea la nota de la Sección 3 antes de asumir que existe uno.';
UPDATE translations SET value = 'Dies ist ein <strong>erster Satz verifizierter Links</strong>, keine vollständige Übersicht aller 66 erfassten Rechtsordnungen. Jeder Link unten wurde direkt anhand der eigenen Website der genannten Regierung/Behörde geprüft. Mehrere Länder in diesem Tracker führen überhaupt kein öffentliches Akkreditierungsregister — siehe den Hinweis in Abschnitt 3, bevor Sie annehmen, dass eines existiert.' WHERE namespace = 'edu-certified-providers' AND lang = 'de' AND key = 'statusBanner.text' AND value = 'Dies ist ein <strong>erster Satz verifizierter Links</strong>, keine vollständige Übersicht aller 60 erfassten Rechtsordnungen. Jeder Link unten wurde direkt anhand der eigenen Website der genannten Regierung/Behörde geprüft. Mehrere Länder in diesem Tracker führen überhaupt kein öffentliches Akkreditierungsregister — siehe den Hinweis in Abschnitt 3, bevor Sie annehmen, dass eines existiert.';
UPDATE translations SET value = 'Il s''agit d''un <strong>premier ensemble de liens vérifiés</strong>, pas d''une cartographie complète des 66 juridictions suivies. Chaque lien ci-dessous a été vérifié directement sur le site propre du gouvernement/de l''autorité mentionné. Plusieurs pays de ce suivi ne gèrent tout simplement aucun registre public d''agrément — consultez la remarque de la section 3 avant de supposer qu''il en existe un.' WHERE namespace = 'edu-certified-providers' AND lang = 'fr' AND key = 'statusBanner.text' AND value = 'Il s''agit d''un <strong>premier ensemble de liens vérifiés</strong>, pas d''une cartographie complète des 60 juridictions suivies. Chaque lien ci-dessous a été vérifié directement sur le site propre du gouvernement/de l''autorité mentionné. Plusieurs pays de ce suivi ne gèrent tout simplement aucun registre public d''agrément — consultez la remarque de la section 3 avant de supposer qu''il en existe un.';
