UPDATE translations SET value = 'E-invoicing thresholds, wave numbers, and go-live dates change constantly — often with little public notice. Subscribe once, and every government update or announcement across the 66 jurisdictions we track lands in your inbox automatically, in plain language, before it catches your team off guard.' WHERE namespace = 'subscribe' AND lang = 'en' AND key = 'benefits.intro' AND value = 'E-invoicing thresholds, wave numbers, and go-live dates change constantly — often with little public notice. Subscribe once, and every government update or announcement across the 60 jurisdictions we track lands in your inbox automatically, in plain language, before it catches your team off guard.';
UPDATE translations SET value = 'Los umbrales de facturación electrónica, los números de ola y las fechas de puesta en marcha cambian constantemente — a menudo con poco aviso público. Suscríbase una vez y cada actualización o anuncio gubernamental de las 66 jurisdicciones que seguimos llegará automáticamente a su bandeja de entrada, en lenguaje sencillo, antes de que sorprenda a su equipo.' WHERE namespace = 'subscribe' AND lang = 'es' AND key = 'benefits.intro' AND value = 'Los umbrales de facturación electrónica, los números de ola y las fechas de puesta en marcha cambian constantemente — a menudo con poco aviso público. Suscríbase una vez y cada actualización o anuncio gubernamental de las 60 jurisdicciones que seguimos llegará automáticamente a su bandeja de entrada, en lenguaje sencillo, antes de que sorprenda a su equipo.';
UPDATE translations SET value = 'E-Invoicing-Schwellenwerte, Wellen-Nummern und Stichtage ändern sich ständig — oft mit wenig öffentlicher Vorankündigung. Einmal abonniert, landet jede Regierungsaktualisierung oder -ankündigung aus den 66 von uns erfassten Rechtsordnungen automatisch in Ihrem Posteingang, in klarer Sprache, bevor sie Ihr Team überrascht.' WHERE namespace = 'subscribe' AND lang = 'de' AND key = 'benefits.intro' AND value = 'E-Invoicing-Schwellenwerte, Wellen-Nummern und Stichtage ändern sich ständig — oft mit wenig öffentlicher Vorankündigung. Einmal abonniert, landet jede Regierungsaktualisierung oder -ankündigung aus den 60 von uns erfassten Rechtsordnungen automatisch in Ihrem Posteingang, in klarer Sprache, bevor sie Ihr Team überrascht.';
UPDATE translations SET value = 'Les seuils de facturation électronique, les numéros de vague et les dates de mise en service changent constamment — souvent avec peu de préavis public. Abonnez-vous une fois, et chaque mise à jour ou annonce gouvernementale des 66 juridictions que nous suivons arrive automatiquement dans votre boîte de réception, en langage clair, avant qu''elle ne prenne votre équipe au dépourvu.' WHERE namespace = 'subscribe' AND lang = 'fr' AND key = 'benefits.intro' AND value = 'Les seuils de facturation électronique, les numéros de vague et les dates de mise en service changent constamment — souvent avec peu de préavis public. Abonnez-vous une fois, et chaque mise à jour ou annonce gouvernementale des 60 juridictions que nous suivons arrive automatiquement dans votre boîte de réception, en langage clair, avant qu''elle ne prenne votre équipe au dépourvu.';
UPDATE translations SET value = 'Tell us which of the 66 jurisdictions matter to your business, and your monthly notification email tells you specifically whether they came up — or get the full global digest if you''d rather see everything.' WHERE namespace = 'subscribe' AND lang = 'en' AND key = 'benefits.item2.body' AND value = 'Tell us which of the 60 jurisdictions matter to your business, and your monthly notification email tells you specifically whether they came up — or get the full global digest if you''d rather see everything.';
UPDATE translations SET value = 'Díganos cuáles de las 66 jurisdicciones importan a su negocio, y su correo de notificación mensual le dirá específicamente si aparecieron — o reciba el resumen global completo si prefiere verlo todo.' WHERE namespace = 'subscribe' AND lang = 'es' AND key = 'benefits.item2.body' AND value = 'Díganos cuáles de las 60 jurisdicciones importan a su negocio, y su correo de notificación mensual le dirá específicamente si aparecieron — o reciba el resumen global completo si prefiere verlo todo.';
UPDATE translations SET value = 'Teilen Sie uns mit, welche der 66 Rechtsordnungen für Ihr Unternehmen relevant sind, und Ihre monatliche Benachrichtigungs-E-Mail sagt Ihnen konkret, ob sie vorkamen — oder erhalten Sie den vollständigen globalen Digest, wenn Sie lieber alles sehen möchten.' WHERE namespace = 'subscribe' AND lang = 'de' AND key = 'benefits.item2.body' AND value = 'Teilen Sie uns mit, welche der 60 Rechtsordnungen für Ihr Unternehmen relevant sind, und Ihre monatliche Benachrichtigungs-E-Mail sagt Ihnen konkret, ob sie vorkamen — oder erhalten Sie den vollständigen globalen Digest, wenn Sie lieber alles sehen möchten.';
UPDATE translations SET value = 'Indiquez-nous lesquelles des 66 juridictions concernent votre entreprise, et votre e-mail de notification mensuel vous dira précisément si elles ont été concernées — ou recevez la synthèse mondiale complète si vous préférez tout voir.' WHERE namespace = 'subscribe' AND lang = 'fr' AND key = 'benefits.item2.body' AND value = 'Indiquez-nous lesquelles des 60 juridictions concernent votre entreprise, et votre e-mail de notification mensuel vous dira précisément si elles ont été concernées — ou recevez la synthèse mondiale complète si vous préférez tout voir.';
UPDATE translations SET value = 'Optional — leave everything unchecked and we''ll send the full monthly digest covering all 66 jurisdictions.' WHERE namespace = 'subscribe' AND lang = 'en' AND key = 'card.countriesHint' AND value = 'Optional — leave everything unchecked and we''ll send the full monthly digest covering all 60 jurisdictions.';
UPDATE translations SET value = 'Opcional — deje todo sin marcar y le enviaremos el resumen mensual completo de las 66 jurisdicciones.' WHERE namespace = 'subscribe' AND lang = 'es' AND key = 'card.countriesHint' AND value = 'Opcional — deje todo sin marcar y le enviaremos el resumen mensual completo de las 60 jurisdicciones.';
UPDATE translations SET value = 'Optional — lassen Sie alles unmarkiert, und wir senden Ihnen den vollständigen monatlichen Digest für alle 66 Rechtsordnungen.' WHERE namespace = 'subscribe' AND lang = 'de' AND key = 'card.countriesHint' AND value = 'Optional — lassen Sie alles unmarkiert, und wir senden Ihnen den vollständigen monatlichen Digest für alle 60 Rechtsordnungen.';
UPDATE translations SET value = 'Facultatif — laissez tout décoché et nous vous enverrons la synthèse mensuelle complète couvrant les 66 juridictions.' WHERE namespace = 'subscribe' AND lang = 'fr' AND key = 'card.countriesHint' AND value = 'Facultatif — laissez tout décoché et nous vous enverrons la synthèse mensuelle complète couvrant les 60 juridictions.';
